// ---- Class Form Modal (ThÃªm / Sá»­a) ----
const ClassFormModal = ({ mode, initial, teachers, onClose, onSave }) => {
  const DAYS = ['Chá»§ nháº­t','Thá»© 2','Thá»© 3','Thá»© 4','Thá»© 5','Thá»© 6','Thá»© 7'];
  const emptyForm = { name:'', type:'vip', description:'', trial_student_name:'', class_link:'', max_students:30, total_sessions:10, teacher_id:'', day_of_week:'1', start_time:'18:00', end_time:'18:45' };

  const [form, setForm] = useState(initial ? {
    name:         initial.name || '',
    type:         initial.type || 'vip',
    description:  initial.description || '',
    trial_student_name: initial.trial_student_name || '',
    class_link:   initial.class_link || '',
    max_students: initial.max_students || 30,
    total_sessions: initial.total_sessions || 10,
    teacher_id:   initial.teacher_id || '',
    day_of_week:  String(initial.day_of_week ?? '1'),
    start_time:   initial.start_time?.substring(0,5) || '18:00',
    end_time:     initial.end_time?.substring(0,5) || '18:45',
  } : emptyForm);

  // Student picker state
  const [allStudents, setAllStudents]     = useState([]);
  const [selectedIds, setSelectedIds]     = useState([]);
  const [studentSearch, setStudentSearch] = useState('');
  const [loadingStudents, setLoadingStudents] = useState(false);
  // Existing students (edit mode)
  const [existingStudents, setExistingStudents] = useState([]);
  const [removingId, setRemovingId] = useState(null);

  const [loading, setLoading] = useState(false);
  const [err, setErr]         = useState('');

  const set = (k, v) => setForm(p => ({ ...p, [k]: v }));
  const maxSt = Number(form.max_students) || 30;
  const isTrial = form.type === 'trial';

  // Load students
  useEffect(() => {
    setLoadingStudents(true);
    if (isTrial) {
      setAllStudents([]);
      setExistingStudents([]);
      setLoadingStudents(false);
    } else if (mode === 'add') {
      axios.get(`${API}/admin/students/all`)
        .then(r => setAllStudents(r.data.students || []))
        .catch(() => setAllStudents([]))
        .finally(() => setLoadingStudents(false));
    } else {
      // Edit: load existing + available
      Promise.all([
        axios.get(`${API}/admin/classes/${initial.id}/students`),
        axios.get(`${API}/admin/classes/${initial.id}/available-students`),
      ]).then(([ex, av]) => {
        setExistingStudents(ex.data.students || []);
        setAllStudents(av.data.students || []);
      }).catch(() => {}).finally(() => setLoadingStudents(false));
    }
  }, [mode, initial, isTrial]);

  const toggleStudent = (id) => {
    setSelectedIds(prev => {
      if (prev.includes(id)) return prev.filter(x => x !== id);
      const currentTotal = mode === 'edit' ? existingStudents.length + prev.length : prev.length;
      if (currentTotal >= maxSt) { setErr(`ÄÃ£ Ä‘áº¡t sÄ© sá»‘ tá»‘i Ä‘a (${maxSt})`); return prev; }
      setErr('');
      return [...prev, id];
    });
  };

  const handleRemoveExisting = async (studentId) => {
    setRemovingId(studentId);
    try {
      await axios.delete(`${API}/admin/classes/${initial.id}/students/${studentId}`);
      setExistingStudents(prev => prev.filter(s => s.id !== studentId));
      // Add back to available list
      const removed = existingStudents.find(s => s.id === studentId);
      if (removed) setAllStudents(prev => [...prev, removed].sort((a,b) => a.full_name.localeCompare(b.full_name)));
    } catch { setErr('Lá»—i xÃ³a há»c sinh'); }
    finally { setRemovingId(null); }
  };

  const filteredStudents = allStudents.filter(s =>
    s.full_name.toLowerCase().includes(studentSearch.toLowerCase()) ||
    s.username.toLowerCase().includes(studentSearch.toLowerCase())
  );

  const handleSave = async () => {
    if (!form.name.trim()) return setErr('Vui lÃ²ng nháº­p tÃªn lá»›p');
    if (isTrial && !form.trial_student_name.trim()) return setErr('Vui lÃƒÂ²ng nhÃ¡ÂºÂ­p tÃƒÂªn hÃ¡Â»Âc sinh hÃ¡Â»Âc thÃ¡Â»Â­');
    setLoading(true); setErr('');
    try {
      if (mode === 'add') {
        await axios.post(`${API}/admin/classes`, { ...form, student_ids: isTrial ? [] : selectedIds });
      } else {
        await axios.put(`${API}/admin/classes/${initial.id}`, form);
        if (initial.schedule_id) {
          await axios.put(`${API}/admin/schedules/${initial.schedule_id}`, {
            day_of_week: form.day_of_week, start_time: form.start_time,
            end_time: form.end_time, teacher_id: form.teacher_id || initial.teacher_id,
          });
        }
        if (!isTrial && selectedIds.length > 0) {
          await axios.post(`${API}/admin/classes/${initial.id}/enroll`, { student_ids: selectedIds });
        }
      }
      onSave();
    } catch (e) {
      setErr(e.response?.data?.message || 'Lá»—i lÆ°u dá»¯ liá»‡u');
    } finally { setLoading(false); }
  };

  const currentTotal = mode === 'edit'
    ? existingStudents.length + selectedIds.length
    : selectedIds.length;

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal class-modal">
        <div className="modal-header">
          <h3 className="modal-title">{mode === 'add' ? 'âž• ThÃªm lá»›p há»c má»›i' : 'âœï¸ Sá»­a lá»›p há»c'}</h3>
          <button className="modal-close" onClick={onClose}>âœ•</button>
        </div>

        <div className="modal-body">
          {err && <div className="form-msg error">{err}</div>}

          {/* ---- ThÃ´ng tin lá»›p ---- */}
          <div className="modal-section-title">ðŸ“‹ ThÃ´ng tin lá»›p</div>
          <div className="form-grid-2">
            <div className="form-group full-col">
              <label>TÃªn lá»›p *</label>
              <input value={form.name} onChange={e => set('name', e.target.value)} placeholder="VD: GD_ENG_001" />
            </div>
 
            {isTrial && (
              <div className="form-group full-col">
                <label>Ten hoc sinh hoc thu *</label>
                <input
                  value={form.trial_student_name}
                  onChange={e => set('trial_student_name', e.target.value)}
                  placeholder="Nhap ten hoc sinh"
                />
              </div>
            )}

            <div className="form-group">
              <label>Loáº¡i lá»›p</label>
              <select value={form.type} onChange={e => set('type', e.target.value)}>
                <option value="vip">VIP</option>
                <option value="trial">Tráº£i nghiá»‡m</option>
              </select>
            </div>

            <div className="form-group" style={{ display: isTrial ? 'none' : undefined }}>
              <label>SÄ© sá»‘ tá»‘i Ä‘a</label>
              <input type="number" min="1" max="100" value={form.max_students}
                onChange={e => set('max_students', e.target.value)} />
            </div>

            <div className="form-group" style={{ display: isTrial ? 'none' : undefined }}>
              <label>Tá»•ng sá»‘ buá»•i há»c</label>
              <input type="number" min="1" max="100" value={form.total_sessions}
                onChange={e => set('total_sessions', e.target.value)} />
            </div>

            <div className="form-group full-col">
              <label>ðŸ”— Link lá»›p há»c (Meet / Zoom / Teams...)</label>
              <input value={form.class_link}
                onChange={e => set('class_link', e.target.value)}
                placeholder="https://meet.google.com/xxx-xxxx-xxx" />
            </div>

            <div className="form-group full-col">
              <label>GiÃ¡o viÃªn phá»¥ trÃ¡ch</label>
              <select value={form.teacher_id} onChange={e => set('teacher_id', e.target.value)}>
                <option value="">â€” ChÆ°a chá»n â€”</option>
                {teachers.map(t => <option key={t.id} value={t.id}>{t.full_name}</option>)}
              </select>
            </div>

            <div className="form-group">
              <label>NgÃ y há»c trong tuáº§n</label>
              <select value={form.day_of_week} onChange={e => set('day_of_week', e.target.value)}>
                {DAYS.map((d, i) => <option key={i} value={i}>{d}</option>)}
              </select>
            </div>

            <div className="form-group">
              <label>Giá» báº¯t Ä‘áº§u</label>
              <input type="time" value={form.start_time} onChange={e => set('start_time', e.target.value)} />
            </div>

            <div className="form-group">
              <label>Giá» káº¿t thÃºc</label>
              <input type="time" value={form.end_time} onChange={e => set('end_time', e.target.value)} />
            </div>

            <div className="form-group full-col">
              <label>MÃ´ táº£</label>
              <textarea value={form.description} onChange={e => set('description', e.target.value)}
                placeholder="MÃ´ táº£ lá»›p há»c..." rows={2} />
            </div>
          </div>

          {/* ---- Há»c sinh ---- */}
          {!isTrial && (<><div className="modal-section-title" style={{marginTop:20}}>
            ðŸ‘¥ Há»c sinh
            <span className="student-count-chip">
              {currentTotal} / {maxSt}
            </span>
          </div>

          {/* Existing students (edit mode) */}
          {mode === 'edit' && existingStudents.length > 0 && (
            <div className="existing-students">
              <div className="existing-label">Äang trong lá»›p</div>
              <div className="existing-list">
                {existingStudents.map(s => (
                  <div key={s.id} className="existing-chip">
                    <span className="existing-chip-name">{s.full_name}</span>
                    <button
                      className="existing-chip-remove"
                      onClick={() => handleRemoveExisting(s.id)}
                      disabled={removingId === s.id}
                      title="XÃ³a khá»i lá»›p"
                    >
                      {removingId === s.id ? '...' : 'Ã—'}
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Search + pick students */}
          <div className="student-picker">
            <div className="student-picker-search">
              <span className="search-icon"><SearchIcon /></span>
              <input
                className="search-input"
                placeholder="TÃ¬m há»c sinh theo tÃªn, username..."
                value={studentSearch}
                onChange={e => setStudentSearch(e.target.value)}
              />
            </div>

            {loadingStudents ? (
              <div className="picker-loading">Äang táº£i danh sÃ¡ch há»c sinh...</div>
            ) : filteredStudents.length === 0 ? (
              <div className="picker-empty">
                {studentSearch ? 'KhÃ´ng tÃ¬m tháº¥y há»c sinh' : (mode === 'edit' ? 'Táº¥t cáº£ há»c sinh Ä‘Ã£ trong lá»›p' : 'ChÆ°a cÃ³ há»c sinh nÃ o trong há»‡ thá»‘ng')}
              </div>
            ) : (
              <div className="picker-list">
                {filteredStudents.map(s => {
                  const checked = selectedIds.includes(s.id);
                  const disabled = !checked && currentTotal >= maxSt;
                  return (
                    <div
                      key={s.id}
                      className={`picker-item ${checked ? 'checked' : ''} ${disabled ? 'disabled' : ''}`}
                      onClick={() => !disabled && toggleStudent(s.id)}
                    >
                      <div className={`picker-checkbox ${checked ? 'checked' : ''}`}>
                        {checked && 'âœ“'}
                      </div>
                      <div className="picker-avatar">{s.full_name.charAt(0)}</div>
                      <div className="picker-info">
                        <div className="picker-name">{s.full_name}</div>
                        <div className="picker-username">@{s.username}</div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {selectedIds.length > 0 && (
              <div className="picker-selected-summary">
                âœ“ ÄÃ£ chá»n thÃªm {selectedIds.length} há»c sinh
                <button className="picker-clear" onClick={() => setSelectedIds([])}>Bá» chá»n táº¥t cáº£</button>
              </div>
            )}
          </div></>)}
        </div>

        <div className="modal-footer">
          <button className="btn-secondary" onClick={onClose}>Há»§y</button>
          <button className="btn-primary" onClick={handleSave} disabled={loading}>
            {loading ? 'Äang lÆ°u...' : (mode === 'add' ? 'ThÃªm lá»›p' : 'LÆ°u thay Ä‘á»•i')}
          </button>
        </div>
      </div>
    </div>
  );
};

// ================================================================
