// ================================================================
const ClassesPage = ({ type }) => {
  const DAYS_SHORT = ['CN','T2','T3','T4','T5','T6','T7'];
  const title = type === 'vip' ? 'Quáº£n lÃ­ lá»›p VIP' : 'Quáº£n lÃ­ lá»›p Tráº£i nghiá»‡m';

  const [classes, setClasses]     = useState([]);
  const [teachers, setTeachers]   = useState([]);
  const [loading, setLoading]     = useState(true);
  const [search, setSearch]       = useState('');
  const [showForm, setShowForm]   = useState(false);
  const [editItem, setEditItem]   = useState(null);   // null = add mode
  const [deleteItem, setDeleteItem] = useState(null);
  const [delLoading, setDelLoading] = useState(false);
  const [toast, setToast]         = useState(null);

  const showToast = (msg, ok = true) => {
    setToast({ msg, ok });
    setTimeout(() => setToast(null), 3000);
  };

  const fetchClasses = useCallback(async () => {
    setLoading(true);
    try {
      const r = await axios.get(`${API}/admin/classes`);
      const all = r.data.classes || [];
      setClasses(all.filter(c => c.type === type));
    } catch { setClasses([]); }
    finally { setLoading(false); }
  }, [type]);

  useEffect(() => { fetchClasses(); }, [fetchClasses]);

  useEffect(() => {
    axios.get(`${API}/admin/teachers`)
      .then(r => setTeachers(r.data.teachers || []))
      .catch(() => setTeachers([]));
  }, []);

  const handleDelete = async () => {
    setDelLoading(true);
    try {
      await axios.delete(`${API}/admin/classes/${deleteItem.id}`);
      showToast('ÄÃ£ xÃ³a lá»›p há»c thÃ nh cÃ´ng');
      setDeleteItem(null);
      fetchClasses();
    } catch (e) {
      showToast(e.response?.data?.message || 'Lá»—i xÃ³a lá»›p', false);
    } finally { setDelLoading(false); }
  };

  const handleSaved = () => {
    showToast(editItem ? 'Cáº­p nháº­t lá»›p há»c thÃ nh cÃ´ng' : 'ThÃªm lá»›p há»c thÃ nh cÃ´ng');
    setShowForm(false);
    setEditItem(null);
    fetchClasses();
  };

  const filtered = classes.filter(c =>
    c.name?.toLowerCase().includes(search.toLowerCase()) ||
    c.teacher_name?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="page-content">
      {/* Toast */}
      {toast && (
