const TablePage = ({ title, fetchUrl, columns }) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  useEffect(() => {
    axios.get(fetchUrl)
      .then(r => setData(Object.values(r.data).find(v => Array.isArray(v)) || []))
      .catch(() => setData([]))
      .finally(() => setLoading(false));
  }, [fetchUrl]);

  const filtered = data.filter(row =>
    Object.values(row).some(v => String(v).toLowerCase().includes(search.toLowerCase()))
  );

  return (
    <div className="page-content">
      <div className="page-header-row">
        <div>
          <h1 className="page-title">{title}</h1>
          <p className="page-subtitle">{filtered.length} báº£n ghi</p>
        </div>
      </div>
      <div className="search-bar">
        <span className="search-icon"><SearchIcon/></span>
        <input placeholder="TÃ¬m kiáº¿m..." value={search}
          onChange={e => setSearch(e.target.value)} className="search-input" />
      </div>
      {loading ? (
        <div className="loading-state">Äang táº£i dá»¯ liá»‡u...</div>
      ) : (
        <div className="table-wrapper">
          <table className="data-table">
            <thead><tr>{columns.map(c => <th key={c.key}>{c.label}</th>)}</tr></thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr><td colSpan={columns.length} className="empty-row">ChÆ°a cÃ³ dá»¯ liá»‡u</td></tr>
              ) : filtered.map((row, i) => (
                <tr key={row.id || i}>
                  {columns.map(c => (
                    <td key={c.key}>{c.render ? c.render(row[c.key], row) : (row[c.key] ?? 'â€”')}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

