const RegisterPage = () => {
  const [form, setForm] = useState({ username:'', password:'', full_name:'', role:'student', email:'' });
  const [msg, setMsg]   = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async e => {
    e.preventDefault(); setLoading(true); setMsg(null);
    try {
      await axios.post(`${API}/admin/users`, form);
      setMsg({ type:'success', text:'Táº¡o tÃ i khoáº£n thÃ nh cÃ´ng!' });
      setForm({ username:'', password:'', full_name:'', role:'student', email:'' });
    } catch(err) {
      setMsg({ type:'error', text: err.response?.data?.message || 'Lá»—i táº¡o tÃ i khoáº£n' });
    } finally { setLoading(false); }
  };

  return (
    <div className="page-content">
      <h1 className="page-title">ÄÄƒng kÃ­ tÃ i khoáº£n</h1>
      <div className="form-card">
        {msg && <div className={`form-msg ${msg.type}`}>{msg.text}</div>}
        <form onSubmit={handleSubmit} className="form-grid">
          {[
            { key:'username',  label:'TÃªn tÃ i khoáº£n *', placeholder:'Nháº­p username', required:true },
            { key:'full_name', label:'Há» vÃ  tÃªn *',      placeholder:'Nháº­p há» tÃªn',  required:true },
          ].map(f => (
            <div className="form-group" key={f.key}>
              <label>{f.label}</label>
              <input value={form[f.key]} placeholder={f.placeholder} required={f.required}
                onChange={e => setForm({...form, [f.key]: e.target.value})} />
            </div>
          ))}
          <div className="form-group">
            <label>Máº­t kháº©u *</label>
            <input type="password" value={form.password} placeholder="Nháº­p máº­t kháº©u" required
              onChange={e => setForm({...form, password: e.target.value})} />
          </div>
          <div className="form-group">
            <label>Email</label>
            <input type="email" value={form.email} placeholder="Nháº­p email"
              onChange={e => setForm({...form, email: e.target.value})} />
          </div>
          <div className="form-group">
            <label>Vai trÃ²</label>
            <select value={form.role} onChange={e => setForm({...form, role: e.target.value})}>
              <option value="student">Há»c viÃªn</option>
              <option value="teacher">GiÃ¡o viÃªn</option>
              <option value="admission">TÆ° váº¥n tuyá»ƒn sinh</option>
              <option value="admin">Admin</option>
            </select>
          </div>
          <div className="form-group full-width">
            <button type="submit" className="submit-btn" disabled={loading}>
              {loading ? 'Äang táº¡o...' : 'Táº¡o tÃ i khoáº£n'}
