export default function AdminDashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState(null);

  useEffect(() => {
    axios.get(`${API}/admin/dashboard`).then(r => setStats(r.data.stats)).catch(()=>{});
  }, []);

  const handleLogout = () => { logout(); navigate('/login'); };

  const peopleCols = [
    { key:'id',         label:'#' },
    { key:'full_name',  label:'Há» tÃªn' },
    { key:'username',   label:'TÃ i khoáº£n' },
    { key:'email',      label:'Email' },
    { key:'is_active',  label:'Tráº¡ng thÃ¡i', render: v => <StatusBadge val={v}/> },
    { key:'created_at', label:'NgÃ y táº¡o', render: v => v ? new Date(v).toLocaleDateString('vi-VN') : 'â€”' },
