          <Route path="/teachers"      element={<TablePage title="Quáº£n lÃ­ giÃ¡o viÃªn"  fetchUrl={`${API}/admin/teachers`} columns={peopleCols}/>}/>
          <Route path="/students"      element={<TablePage title="Quáº£n lÃ­ há»c viÃªn"   fetchUrl={`${API}/admin/students`} columns={peopleCols}/>}/>
        </Routes>
